<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('expenses');$pageTitle='New Expense Request';$activeMenu='expense-new';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['expense_date']??'';$dept=(int)($_POST['department_id']??0);$cat=(int)($_POST['category_id']??0);$desc=trim($_POST['description']??'');$amount=(float)($_POST['amount']??0);if(!valid_date($date))$errors[]='Expense date is invalid.';if(!$dept||!request_department_allowed($dept))$errors[]='Select an authorized department.';if(!$cat)$errors[]='Category is required.';if($desc==='')$errors[]='Description is required.';if($amount<=0)$errors[]='Amount must be greater than zero.';if(setting('receipt_required','optional')==='required' && empty($_FILES['receipt']['name']))$errors[]='A receipt attachment is required by system settings.';
 if(!$errors){$code=generate_code('EXP','expenses','expense_code');db()->beginTransaction();try{$s=db()->prepare("INSERT INTO expenses(expense_code,expense_date,department_id,category_id,description,amount,requested_by,status) VALUES(?,?,?,?,?,?,?,'Pending')");$s->execute([$code,$date,$dept,$cat,$desc,$amount,current_user()['id']]);$id=(int)db()->lastInsertId();save_approval_request('expense',$id);
 if(!empty($_FILES['receipt']['name'])){if($_FILES['receipt']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Receipt upload failed.');if($_FILES['receipt']['size']>5*1024*1024)throw new RuntimeException('Receipt must not exceed 5 MB.');$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($_FILES['receipt']['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))throw new RuntimeException('Receipt must be JPG, PNG or PDF.');$stored=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!is_dir(UPLOAD_PATH))mkdir(UPLOAD_PATH,0775,true);if(!move_uploaded_file($_FILES['receipt']['tmp_name'],UPLOAD_PATH.'/'.$stored))throw new RuntimeException('Could not save receipt.');$r=db()->prepare('INSERT INTO expense_receipts(expense_id,original_name,stored_name,mime_type,file_size,uploaded_by) VALUES(?,?,?,?,?,?)');$r->execute([$id,basename($_FILES['receipt']['name']),$stored,$mime,$_FILES['receipt']['size'],current_user()['id']]);}
 db()->commit();log_activity('CREATE','Expense','Created '.$code);flash('success','Expense request submitted for approval.');redirect('expenses/index.php');}catch(Throwable $e){db()->rollBack();$errors[]=$e->getMessage();}}
}
$departments=departments();$categories=categories();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>New Expense Request</h1><p>Submit an expense with optional receipt evidence for manager and Finance review.</p></div><a class="btn btn-light border" href="<?=e(url('expenses/index.php'))?>">Back</a></div><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><div class="row"><div class="col-xl-9"><div class="card-panel"><div class="card-body"><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="row g-3"><div class="col-md-4"><label class="form-label">Expense Date</label><input class="form-control" type="date" name="expense_date" value="<?=e($_POST['expense_date']??date('Y-m-d'))?>" required></div><div class="col-md-4"><label class="form-label">Department</label><select class="form-select" name="department_id" required><option value="">Select department</option><?php foreach($departments as $d):if(role_name()==='Staff' && (int)$d['id']!==(int)current_user()['department_id'])continue;?><option value="<?=$d['id']?>" <?=((int)($_POST['department_id']??current_user()['department_id'])===(int)$d['id'])?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Category</label><select class="form-select" name="category_id" required><option value="">Select category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((int)($_POST['category_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Description / Business Purpose</label><textarea class="form-control" name="description" rows="4" required><?=e($_POST['description']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Amount (PHP)</label><input class="form-control" type="number" name="amount" step="0.01" min=".01" value="<?=e($_POST['amount']??'')?>" required></div><div class="col-md-6"><label class="form-label">Receipt Attachment <span class="text-secondary fw-normal">(optional, max 5MB)</span></label><input class="form-control" type="file" name="receipt" accept="image/jpeg,image/png,application/pdf"></div><div class="col-12"><button class="btn btn-primary px-4"><i class="fa-solid fa-paper-plane me-2"></i>Submit Expense</button></div></div></form></div></div></div><div class="col-xl-3 mt-3 mt-xl-0"><div class="info-banner"><strong>Approval Path</strong><div class="small mt-2">Employee/Staff → Department Manager → Finance Manager → Approved. Only fully approved expenses reduce the available budget on the dashboard.</div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
